<?php if ( ! defined( 'ABSPATH' ) || ! is_user_logged_in() || ! function_exists( 'sd_core_recommend_members' ) ) { return; } $recommendations = sd_core_recommend_members( get_current_user_id(), 6 ); if ( empty( $recommendations ) ) : ?><div class="sd-card sd-empty"><h3><?php esc_html_e( 'No recommendations yet', 'social-discovery' ); ?></h3><p><?php esc_html_e( 'Add a few public interests to improve your recommendations.', 'social-discovery' ); ?></p></div><?php return; endif; ?><section class="sd-recommendations"><div class="sd-section-heading"><span class="sd-eyebrow"><?php esc_html_e( 'Based on your interests', 'social-discovery' ); ?></span><h2><?php esc_html_e( 'People you may know', 'social-discovery' ); ?></h2></div><div class="sd-member-grid"><?php foreach ( $recommendations as $recommendation ) { get_template_part( 'template-parts/discovery/member-card', null, array( 'member' => $recommendation['user'], 'shared_interests' => $recommendation['shared_interests'] ) ); } ?></div></section>
